// route is one route of the hub's API.
type route struct {
	method, path string
	// public routes need no credential.
	public bool
	// list routes answer a page of the list envelope.
	list bool
	// create routes are POSTs that create a resource and take an
	// Idempotency-Key; status is their first answer when it is not 201.
	create bool
	status int
	// maxLimit is the highest limit a list takes when it is not 200.
	maxLimit int
	// feed marks the event log, whose full pages always carry a cursor,
	// since it does not look past a page for more: a walk to its end ends
	// with an empty page whose next_cursor is null.
	feed bool
	// showOnce are the members of a create's answer, by dotted path, that
	// are shown once and left out of a replay.
	showOnce []string
	// seed names the seeding of the envelope scenario that makes the
	// identifiers of the path exist: "" for a path that names none, gateway
	// and forge for resources of a gateway or a forge, which that
	// scenario's hub has neither of, so their identifiers are left
	// nonexistent. The paging and idempotency scenarios give their hubs
	// the fake forge.
	seed string
	// outside is why a list or create route is left out of the paging and
	// idempotency scenarios; it stays in the envelope scenario.
	outside string
}

